(() => {
  'use strict';const $=id=>document.getElementById(id),escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  const stages=['Aguardando pagamento','Pedido confirmado','Em preparação','Coletado pela transportadora','Em transporte','Entregue'];
  const status=value=>({PAID:'Pago',WAITING_PAYMENT:'Pendente',PROCESSING:'Processando',AUTHORIZED:'Aguardando confirmação',REFUSED:'Recusado',REFUNDED:'Estornado',CANCELED:'Cancelado',CHARGEDBACK:'Contestado'}[value]||value);
  const money=value=>(Number(value||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),date=value=>new Date(value).toLocaleString('pt-BR');
  let challenge='',page=1,currentId='';
  async function api(path,body){const response=await fetch('/api/admin'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await response.json();if(!response.ok){if(response.status===401&&!path.startsWith('/login/'))showLogin();throw Error(data.message||'Não foi possível concluir agora.');}return data;}
  function showLogin(){$('login-card').hidden=false;$('dashboard').hidden=true;$('logout').hidden=true;}
  async function load(){const data=await api('/orders?status='+encodeURIComponent($('filter').value)+'&page='+page);$('stats').innerHTML=[['Pedidos',data.stats.total||0],['Pagos',data.stats.paid||0],['Pendentes',data.stats.pending||0],['Total pago',money(data.stats.revenue)]].map(([label,value])=>`<div class="card"><span class="muted">${label}</span><strong>${escape(value)}</strong></div>`).join('');$('orders').innerHTML=data.orders.length?data.orders.map(order=>`<tr><td>${escape(order.order_code)}<small>${escape(date(order.created_at))}</small></td><td>${escape(order.customer.name)}<small>${escape(order.customer.email)}</small></td><td>${escape(money(order.amount))}</td><td><span class="badge ${order.payment_status==='PAID'?'paid':''}">${escape(status(order.payment_status))}</span></td><td>${escape(stages[order.stage])}</td><td><button data-order="${escape(order.id)}">Ver pedido</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhum pedido encontrado. Use “Sincronizar Umbrella” para buscar os pedidos existentes desta loja.</td></tr>';$('page').textContent='Página '+data.page;$('prev').disabled=page<=1;$('next').disabled=!data.hasMore;}
  async function enter(){$('login-card').hidden=true;$('dashboard').hidden=false;$('logout').hidden=false;await load();}
  function action(button,message,fn){return async event=>{if(event)event.preventDefault();button.disabled=true;message.textContent='';try{await fn();}catch(error){message.textContent=error.message;}finally{button.disabled=false;}};}
  $('login-form').addEventListener('submit',action($('login-form').querySelector('button'),$('login-message'),async()=>{const data=await api('/login/request',{email:$('email').value});challenge=data.challenge;$('code-form').hidden=false;$('login-form').hidden=true;$('login-message').textContent=data.message;$('otp').focus();}));
  $('code-form').addEventListener('submit',action($('code-form').querySelector('button'),$('login-message'),async()=>{await api('/login/verify',{challenge,code:$('otp').value});$('otp').value='';await enter();}));
  $('logout').onclick=action($('logout'),$('dashboard-message'),async()=>{await api('/logout',{});showLogin();$('code-form').hidden=true;$('login-form').hidden=false;});
  $('refresh').onclick=action($('refresh'),$('dashboard-message'),load);
  $('filter').onchange=async()=>{page=1;try{await load();}catch(error){$('dashboard-message').textContent=error.message;}};
  $('prev').onclick=async()=>{page=Math.max(1,page-1);try{await load();}catch(error){$('dashboard-message').textContent=error.message;}};
  $('next').onclick=async()=>{page++;try{await load();}catch(error){$('dashboard-message').textContent=error.message;}};
  $('sync').onclick=action($('sync'),$('dashboard-message'),async()=>{let n=1,total=0,more=true;while(more){$('dashboard-message').textContent='Sincronizando pedidos… página '+n;const data=await api('/sync',{page:n});total+=data.synced;more=data.hasMore;n++;}await load();$('dashboard-message').textContent=total+' pedido(s) sincronizado(s).';});
  $('close-dialog').onclick=()=>$('order-dialog').close();
  async function detail(id){currentId=id;const data=await api('/orders/'+encodeURIComponent(id)),order=data.order,a=order.address||{},paid=order.payment_status==='PAID';$('route-message').textContent='';$('order-detail').innerHTML=`<span class="eyebrow">Detalhes do pedido</span><h2>${escape(order.order_code)}</h2><span class="badge ${paid?'paid':''}">${escape(status(order.payment_status))}</span><div class="grid"><div><h3>Cliente</h3><p>${escape(order.customer.name)}<br>${escape(order.customer.email)}<br>${escape(order.customer.phone)}</p></div><div><h3>Endereço</h3><p>${escape([a.street,a.streetNumber,a.complement,a.neighborhood,a.city,a.state,a.zipCode].filter(Boolean).join(', '))}</p></div></div>${order.items.map(item=>`<p class="muted">${escape(item.quantity)} × ${escape(item.title)}</p>`).join('')}<p><strong>Total: ${escape(money(order.amount))}</strong></p><p class="code">${escape(order.tracking_code)}</p><a class="button secondary" target="_blank" rel="noreferrer" href="/rastreio?codigo=${encodeURIComponent(order.tracking_code)}">Abrir acompanhamento</a><h3>Atualizar entrega</h3><p class="notice">Registre uma movimentação após confirmar com a transportadora. O prazo de 15 dias é uma previsão; as etapas não avançam sozinhas.</p>${paid?`<form id="route-form" class="grid"><div><label for="stage">Etapa atual</label><select id="stage" name="stage">${stages.slice(1).map((name,i)=>`<option value="${i+1}" ${order.stage===i+1?'selected':''}>${i+1}. ${name} · dias ${i*3+1}–${(i+1)*3}</option>`).join('')}</select></div><div><label for="occurredAt">Data e hora da movimentação</label><input type="datetime-local" id="occurredAt" name="occurredAt" required></div><div><label for="carrier">Transportadora</label><input id="carrier" name="carrier" maxlength="120" value="${escape(order.carrier)}"></div><div><label for="carrierCode">Código da transportadora (opcional)</label><input id="carrierCode" name="carrierCode" maxlength="120" value="${escape(order.carrier_code)}"></div><div><label for="location">Cidade / local da movimentação</label><input id="location" name="location" maxlength="120"></div><div><label for="estimatedDelivery">Previsão de entrega</label><input id="estimatedDelivery" name="estimatedDelivery" type="date" value="${escape(order.estimated_delivery||'')}"></div><div class="full"><label for="note">Informação que o cliente verá</label><textarea id="note" name="note" rows="3" required maxlength="1500" placeholder="Descreva a movimentação confirmada pela transportadora."></textarea></div><div class="full"><button>Salvar atualização de entrega</button></div></form>`:'<p class="muted">As atualizações de entrega ficam disponíveis após a confirmação do pagamento.</p>'}<h3>Histórico de movimentações</h3><ul class="history">${data.events.length?data.events.map(item=>`<li><time>${escape(date(item.occurred_at))}</time><p><strong>${escape(stages[item.stage])}</strong></p><p>${escape(item.note)}</p><p class="muted">${escape(item.location)}</p></li>`).join(''):'<li class="muted">Ainda não há movimentações.</li>'}</ul>`;
    window.DeliveryMap.prepareAdmin(order,data.events);
    if(paid){const now=new Date();now.setMinutes(now.getMinutes()-now.getTimezoneOffset());$('occurredAt').value=now.toISOString().slice(0,16);$('route-form').addEventListener('submit',action($('route-form').querySelector('button'),$('route-message'),async()=>{const form={...Object.fromEntries(new FormData($('route-form'))),...$('route-form').mapPoint()};form.occurredAt=new Date(form.occurredAt).toISOString();await api('/orders/'+encodeURIComponent(currentId)+'/route',form);await detail(currentId);$('route-message').textContent='Movimentação salva e disponível para o cliente.';await load();}));}
    if(!$('order-dialog').open)$('order-dialog').showModal();
  }
  $('orders').onclick=async event=>{const button=event.target.closest('[data-order]');if(!button)return;button.disabled=true;try{await detail(button.dataset.order);}catch(error){$('dashboard-message').textContent=error.message;}finally{button.disabled=false;}};
  api('/session').then(enter).catch(()=>showLogin());
})();
